        m.code.end();std::vector<Word> expected=count==1?std::vector<Word>{UINT32_MAX}:std::vector<Word>(playing.begin(),playing.begin()+static_cast<std::ptrdiff_t>(count));format_expect_numeric(script(m),profile,system_function,music_code,expected);
