    suite.test("unreachable non-stop MUSIC loads without dispatch",[]{Model m;m.code.end();m.code.music(1,0);m.code.end();FormatEventProbe h;nnn::CExecScript vm(h);h.vm=&vm;load(vm,m);const auto r=vm.Exec();require(r.status.code==ErrorCode::Ok&&r.pc==32&&r.work_used==4&&h.events.empty()&&h.skipped.empty(),"unreachable MUSIC executed");});
    suite.test("failed load preserves old PC SUB and music state",[]{Model m;m.strings={"S"};m.code.sub(0);m.code.print();m.code.end();m.targets={m.code.story()};m.code.music();m.code.add({3,control,0x55560007U});MusicHost h;nnn::CExecScript vm(h);h.vm=&vm;h.apply_controller=true;const auto initial=seed();status_is(h.music.SetState(initial),ErrorCode::Ok,"transaction state");h.output=[](Word,bool,Value)->bool{throw std::runtime_error("stop");};load(vm,m,ScriptControlProfile::Foreground);status_is(vm.Exec().status,ErrorCode::CallbackFailed,"nested output throw");const auto stack=frames(vm);const auto state=h.music.State();status_is(vm.LoadBytes({0,0,0,0},"bad"),ErrorCode::InvalidFormat,"failed bytes");require(vm.GetPC()==51&&frames(vm)==stack&&stack==std::vector<std::pair<Word,Word>>{{37,0}}&&vm.Identity()=="music"&&vm.HasForegroundControls()&&equal(h.music.State(),state),"failed load mutated VM/music state");});
