        for(Word initial=0;initial<32;++initial){MusicHost h;std::vector<std::string> requests;nnn::ScriptScheduler owner(h,[&](const std::string& key){requests.push_back(key);require(key=="spt/child.spt","wrong child key");const auto input=script(child);return nnn::ReadResult{{},input,input.size()};});h.owner=&owner;h.apply_controller=true;h.SetSkipFlags(flags(initial));h.variables[100]=29;const auto before=seed(1,1,2);status_is(h.music.SetState(before),ErrorCode::Ok,"child music state");int outputs=0;h.output=[&](Word slot,bool fade,Value time){++outputs;require(slot==1&&!fade&&time==0&&owner.ActiveMode()==nnn::ScriptMode::Main&&owner.GetVM(nnn::ScriptMode::Main)->GetPC()==(labels?45U:32U),"output wrong active slot/mode/PC");auto during=before;during.target_volume=0;require(equal(h.music.State(),during),"output state order");status_is(owner.Step().status,ErrorCode::Busy,"output nested owner");status_is(h.music.StopNow({}),ErrorCode::Busy,"output nested controller");return false;};status_is(owner.LoadBytes(script(root),"control"),ErrorCode::Ok,"owner load");const auto push=owner.Step();status_is(push.status,ErrorCode::Ok,"push");const auto pop=owner.Step();status_is(pop.status,ErrorCode::Ok,"music then NEXT");require(pop.executed_mode==nnn::ScriptMode::Main&&pop.active_mode==nnn::ScriptMode::Control&&pop.transitions==1&&pop.return_code==0x55560006U&&owner.GetVM(nnn::ScriptMode::Control)->GetPC()==37,"stop yielded or parent ran during pop");const auto r=owner.Exec();status_is(r.status,ErrorCode::Ok,"parent PRINT");require(r.return_code==print_code&&h.retained.size()==1&&outputs==(suppressed(initial)?0:1)&&equal(h.music.State(),expected_stop(before,initial))&&mask(h.GetSkipFlags())==initial&&h.variables[100]==29,"shared host/source music result");const auto numeric_index=labels?2U:1U;require(h.states[numeric_index].mode==1&&h.states[numeric_index].pc==(labels?45U:32U)&&h.states[numeric_index].stack.size()==(labels?1U:0U),"numeric current child/frame");Word slot=9;require(owner.GetVM(nnn::ScriptMode::Control)->GetScriptCallSlot(slot)&&slot==0&&requests==std::vector<std::string>{"spt/child.spt"},"stop changed call slot or read assets");}
